def trace_T4(reference_controllers, controllers, device, labels, run_id):
    import sys,time,json,collections
    from pathlib import Path
    sys.path.insert(0,'results/T-048/scripts')
    from chay import OUT,read,dump,sha
    from kiem import read_run,doi_chieu_khoa
    from cham import WORLDS
    folder=OUT/'runs'/run_id;folder.mkdir();started=time.monotonic()
    allocation=read(OUT/'ma-tran.json')['allocation']; refs={};hashes={}
    # Verify all original raw hashes again before using scoring roots.
    for parents in (reference_controllers,controllers):
      for name in parents:
       status=read(OUT/'runs'/name/'kiem.json')
       for child in status['finished']:
        cmd,meta,pairs=read_run(OUT/'runs'/child);hashes[child]=meta
    (folder/'command.json').write_text(dump(dict(reference_controllers=reference_controllers,controllers=controllers,device=device,phase1=hashes,labels_sha256=__import__('hashlib').sha256(dump(labels).encode()).hexdigest(),analysis_source=ANALYSIS_SOURCE))+'\n',encoding='utf-8')
    for name in reference_controllers:
      for child in read(OUT/'runs'/name/'kiem.json')['finished']:
       cmd,meta,pairs=read_run(OUT/'runs'/child)
       for j in cmd['plan']['jobs']:
        if allocation[j['opaque_id']]==device:refs[(j['opaque_id'],j['window'])]=child
    stats={};records=0
    with (folder/'trung-gian.jsonl').open('x',encoding='utf-8') as output,(folder/'progress.jsonl').open('x',encoding='utf-8') as progress:
      for name in controllers:
       for child in read(OUT/'runs'/name/'kiem.json')['finished']:
        _,_,pairgen=read_run(OUT/'runs'/child); first=None
        for r,d in pairgen():
         oid=r['opaque_id'];window=d['window'];cid=r['config_id']
         if allocation[oid]!=device:continue
         if first is None:
          refchild=refs[(oid,window)];_,_,rp=read_run(OUT/'runs'/refchild);r0,d0=next(rp());first=(r0,d0)
         r0,d0=first;t0=d0['trace'];t=d['trace']
         assert t['normalized_input_sha256']==t0['normalized_input_sha256'] and t['cong_G3']==t0['cong_G3']
         assert t['phan_vi'].keys()==t0['phan_vi'].keys()
         assert all(t['phan_vi'][u]['mau_sha256']==t0['phan_vi'][u]['mau_sha256'] for u in t['phan_vi'])
         entry=dict(opaque_id=oid,window=window,dataset=d['dataset'],config_id=cid,reference_child=refchild,child=child,input_equal=True,worlds={})
         for i,w in enumerate(WORLDS):
          a,b=t0['world_state'][w],t['world_state'][w]
          ua,ub=({x['don_vi']['ma']:x for x in q['units']} for q in (a,b));assert ua.keys()==ub.keys()
          flags=[];values=collections.Counter();max_p=0
          for u in ua:
           x,y=ua[u]['cham'],ub[u]['cham'];fs=('trang_thai','hop_le','F_raw_len','F_raw_xuong')
           if any(x.get(k)!=y.get(k) for k in fs):
            keep=(*fs,'e_len','e_xuong','e_len_tho','e_xuong_tho','p_len','p_xuong','h','l','r_len_A','r_xuong_A')
            flags.append(dict(unit=u,kind=ua[u]['don_vi']['loai'],before={k:x.get(k) for k in keep},after={k:y.get(k) for k in keep}))
           for k in ('p_len','p_xuong','h','l','r_len_A','r_xuong_A','e_len','e_xuong'):
            if x.get(k)!=y.get(k):values[k]+=1
           for k in ('p_len','p_xuong'):
            if isinstance(x.get(k),(int,float)) and isinstance(y.get(k),(int,float)):max_p=max(max_p,abs(x[k]-y[k]))
          ar,br=t0['xep'][i],t['xep'][i]; root=labels[oid]['root']; keya=doi_chieu_khoa(ar,root);keyb=doi_chieu_khoa(br,root)
          flips=[]
          def pos(rank):return {e:n for n,block in enumerate(rank['ket_qua']['blocks']) for group in block['groups'] for e in group}
          pa,pb=pos(ar),pos(br)
          if root in pa and root in pb:
           for rival in sorted(pa.keys()&pb.keys()-{root}):
            old=(pa[root]>pa[rival])-(pa[root]<pa[rival]);new=(pb[root]>pb[rival])-(pb[root]<pb[rival])
            if old!=new:flips.append(dict(rival=rival,before_relation=old,after_relation=new,before=doi_chieu_khoa(ar,rival),after=doi_chieu_khoa(br,rival)))
          row=dict(changed_flags=flags,value_changes=dict(values),max_abs_delta_p=max_p,tier_changes={e:[ar['ket_qua']['tang'][e],br['ket_qua']['tang'][e]] for e in ar['ket_qua']['tang'] if ar['ket_qua']['tang'][e]!=br['ket_qua']['tang'][e]},root_keys=[keya,keyb],root_pair_flips=flips,N1=[a['N1'],b['N1']],V0=[a['V0'],b['V0']],valid_units=[a['valid_units'],b['valid_units']])
          entry['worlds'][w]=row
          st=stats.setdefault(cid,{}).setdefault(w,collections.Counter());st.update(windows=1,windows_with_flag_changes=bool(flags),changed_units=len(flags),windows_with_tier_changes=bool(row['tier_changes']),root_pair_flips=len(flips))
         output.write(dump(entry)+'\n');output.flush();records+=1
        progress.write(dump(dict(child=child,records=records,elapsed=time.monotonic()-started))+'\n');progress.flush()
    (folder/'kiem.json').write_text(dump(dict(closed=True,records=records,stats=stats,phase1=hashes,trace_sha256=sha(folder/'trung-gian.jsonl'),wall_seconds=time.monotonic()-started))+'\n',encoding='utf-8')
    return dict(records=records,wall_seconds=time.monotonic()-started)
